<?php $this->breadcrumbs=array('Công việc'); $tabs=array('mine'=>'Của tôi','today'=>'Hôm nay','upcoming'=>'Sắp tới','overdue'=>'Quá hạn','completed'=>'Đã hoàn thành','all'=>'Tất cả'); ?>
<h1>Công việc</h1>
<p><?php if (ActionAccess::can('task','create') && !empty(Yii::app()->params['mvp']['taskWrite'])) { echo CHtml::link('Thêm công việc',array('create'),array('class'=>'btn btn-primary')); } ?> <?php if (ActionAccess::can('task','calendar')) { echo CHtml::link('Lịch tuần',array('calendar'),array('class'=>'btn btn-default')); } ?></p>
<ul class="nav nav-tabs"><?php foreach ($tabs as $id=>$label): ?><li<?php echo $tab===$id?' class="active"':''; ?>><?php echo CHtml::link($label,array_merge(array('admin','tab'=>$id,'timezone'=>$timezone),$filters)); ?></li><?php endforeach; ?></ul>
<?php echo CHtml::beginForm(array('admin'),'get'); echo CHtml::hiddenField('tab',$tab); echo CHtml::hiddenField('timezone',$timezone); if ($filters['account_id']!=='') { echo CHtml::hiddenField('account_id',$filters['account_id']); } $this->renderPartial('_filters',compact('filters','hotels','owners')); echo CHtml::submitButton('Lọc',array('class'=>'btn btn-default')); echo CHtml::endForm(); ?>
<p>Ngày/giờ hiển thị theo <?php echo CHtml::encode($timezone); ?>; việc hạn ngày giữ ngày và timezone của công việc.</p>
<table class="table table-striped"><thead><tr><th>Công việc</th><th>Khách hàng / khách sạn</th><th>Hạn</th><th>Sales</th><th>Ưu tiên / Trạng thái</th></tr></thead><tbody>
<?php foreach ($tasks as $t): ?><tr><td><?php echo CHtml::link(CHtml::encode($t->code.' · '.$t->title),array('view','id'=>$t->id)); ?></td><td><?php echo CHtml::encode($t->account->name.' / '.$t->hotel->name); ?></td><td><?php echo CHtml::encode($t->due_mode==='date'?$t->due_date.' ('.$t->timezone.')':str_replace('T',' ',TaskSchedule::local($t->due_at_utc,$timezone))); ?></td><td><?php echo CHtml::encode($t->assignee?$t->assignee->fullname:'#'.$t->assignee_user_id); ?></td><td><?php echo CHtml::encode(($t->priority==='high'?'Cao':'Bình thường').' · '.TaskReadService::labels()[$t->status]); echo $t->isOverdue()?' · Quá hạn':''; ?></td></tr><?php endforeach; ?>
<?php if (!$tasks): ?><tr><td colspan="5">Chưa có công việc phù hợp trong phạm vi truy cập.</td></tr><?php endif; ?></tbody></table>
<?php $this->renderPartial('/account/_pager',array('page'=>$page,'total'=>$total,'route'=>array_merge(array('admin','tab'=>$tab,'timezone'=>$timezone),$filters))); ?>
